import axiosConfig from "../axiosConfig"
export const apiGetVirulenceInfo = async (file) => {
    try {
        const formData = new FormData();
        formData.append('fasta', file);

        const response = await axiosConfig.post('/api/virulence/getvirulenceinfo', formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
                'Accept': 'application/json',
            }
        });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const apiGetVirulenceInfoPlasmid = async(plasmid) =>{
    try{
        const response = await axiosConfig.post('/api/virulence/getvirulenceinfoplasmid', {plasmid: plasmid})
        return response.data;
    }catch (error) {
        throw error.response?.data || error.message;
    }
}

export const apiGetCircularPlot = async(data) =>{
    try {
        const response = await axiosConfig.post('/api/virulence/plotcircular', {data: data})
    } catch (error) {
        throw error.response?.data || error.message;
    }
}
